import Templates from "core/templates";
import { TEMPLATES } from "./template";

/**
 * Enhanced template renderer with caching and cleaner API.
 *
 * Features:
 * - Caches DOM element references for better performance
 * - Maps template types to element IDs automatically
 * - Validates callbacks before execution
 * - Provides dedicated error rendering method
 *
 * @module mod_tutoom/lib/template_renderer
 * @copyright 2025 onwards, Tutoom Inc.
 * @license http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Template Renderer class for efficient template rendering.
 */
export class TemplateRenderer {
  /**
   * Constructor - initializes cache and element mapping.
   */
  constructor() {
    this.elementCache = {};
    this.elementMap = {
      [TEMPLATES.MAIN_SECTION]: "tutoom-main-section",
      [TEMPLATES.RECORDING_SECTION]: "tutoom_view_recordings",
      [TEMPLATES.RECORDING_TABLE_CONTENT]: "tutoom-recordings-table-content",
      [TEMPLATES.RECORDING_PAGINATION]: "tutoom_view_recordings_pagination",
    };
  }

  /**
   * Get DOM element for template type (with caching).
   *
   * @param {string} templateType - Template type from TEMPLATES constant
   * @returns {HTMLElement|null} DOM element or null if not found
   */
  getElement(templateType) {
    if (!this.elementCache[templateType]) {
      const elementId = this.elementMap[templateType];
      if (!elementId) {
        return null;
      }
      this.elementCache[templateType] = document.getElementById(elementId);
    }
    return this.elementCache[templateType];
  }

  /**
   * Render template to DOM.
   *
   * @param {Object} params - Rendering parameters
   * @param {Object} params.data - Data to pass to template
   * @param {string} params.type - Template type from TEMPLATES constant
   * @param {Function} [params.callbackBeforeRender] - Optional callback before rendering
   * @param {Function} [params.callbackAfterRender] - Optional callback after rendering
   * @returns {Promise<void>}
   * @throws {Error} If element not found for template type
   */
  async render({ data, type, callbackBeforeRender, callbackAfterRender }) {
    const el = this.getElement(type);
    if (!el) {
      throw new Error(`Element not found for template type: ${type}`);
    }

    const { html, js } = await Templates.renderForPromise(type, data || {});

    if (typeof callbackBeforeRender === 'function') {
      callbackBeforeRender();
    }

    Templates.replaceNodeContents(el, html, js);

    if (typeof callbackAfterRender === 'function') {
      callbackAfterRender();
    }
  }

  /**
   * Convenience method for rendering error data.
   *
   * @param {Object} errorData - Error data object from error handlers
   * @param {string} templateType - Template type from TEMPLATES constant
   * @returns {Promise<void>}
   */
  async renderError(errorData, templateType) {
    await this.render({ data: errorData, type: templateType });
  }

  /**
   * Clear element cache (useful for testing or dynamic content).
   *
   * @returns {void}
   */
  clearCache() {
    this.elementCache = {};
  }
}
