/**
 * Centralized API service for Tutoom AJAX operations.
 *
 * Handles all fetch/parse/error handling logic in a reusable way.
 *
 * @module mod_tutoom/lib/api_service
 * @copyright 2025 onwards, Tutoom Inc.
 * @license http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * API Service class for centralized fetch operations.
 *
 * Features:
 * - Automatic URL construction with sesskey
 * - JSON parsing with error handling
 * - Tutoom data validation
 * - Normalized response structure
 */
export class ApiService {
  /**
   * Fetch data from API and parse JSON response.
   *
   * @param {string} action - The AJAX action to perform
   * @param {Object} params - Additional parameters to include in the request
   * @returns {Promise<{success: boolean, data?: Object, parseError?: boolean}>}
   *   Returns object with success flag and either data or parseError
   */
  async fetchAndParse(action, params = {}) {
    const tutoom = this.getTutoomData();
    const url = this.buildUrl(tutoom.baseUrl, action, {
      id: tutoom.id,
      ...params
    });

    const fetchResponse = await window.fetch(url);
    return await this.parseResponse(fetchResponse);
  }

  /**
   * Build API URL with query parameters.
   *
   * @param {string} baseUrl - Base URL for the API
   * @param {string} action - The AJAX action
   * @param {Object} params - Query parameters
   * @returns {string} Complete URL with query string
   */
  buildUrl(baseUrl, action, params) {
    const searchParams = new URLSearchParams({
      action,
      sesskey: M.cfg.sesskey,
      ...params
    });
    return `${baseUrl}?${searchParams.toString()}`;
  }

  /**
   * Parse JSON response with error handling.
   *
   * @param {Response} response - Fetch response object
   * @returns {Promise<{success: boolean, data?: Object, parseError?: boolean}>}
   */
  async parseResponse(response) {
    try {
      const data = await response.json();
      return { success: true, data };
    } catch (error) {
      return { success: false, parseError: true };
    }
  }

  /**
   * Get and validate Tutoom data from window object.
   *
   * @returns {Object} Tutoom configuration data
   * @throws {Error} If tutoom data is not available
   */
  getTutoomData() {
    const tutoom = window.tutoom;
    if (!tutoom || tutoom === undefined) {
      throw new Error("Tutoom data is empty");
    }
    return tutoom;
  }
}
